import { Controller, Delete, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 재기안 기반으로 선택할 수 있는 기작성 문서 상태
const REDRAFTABLE_STATUSES = ['반려', '회수', '승인', '완료'];
// 가정: 삭제 가능한 상태
const DELETABLE_STATUSES = ['반려', '회수'];

@Controller('api/v1')
export class FnSfr029107X9c9389Controller {
  @Delete('/approval-documents/:approvalDocumentId')
  async deleteApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const documentId = req.params['approvalDocumentId'];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT approval_document_id AS "approvalDocumentId",
                drafter_id AS "drafterId",
                title AS "title",
                document_number AS "documentNumber",
                approval_status AS "approvalStatus"
           FROM approval_document
          WHERE approval_document_id = CAST(:documentId AS bigint)
          FOR UPDATE`,
        { documentId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      const doc = rows[0];
      if (String(doc.drafterId) !== String(user.id)) {
        throw new ApiError(422, 'NOT_DRAFTER', '기안자만 문서를 삭제할 수 있습니다.');
      }
      if (!DELETABLE_STATUSES.includes(doc.approvalStatus)) {
        throw new ApiError(409, 'APPROVAL_DOCUMENT_STATUS_MISMATCH', '반려 또는 회수 상태의 문서만 삭제할 수 있습니다.');
      }
      await db.execute(
        `DELETE FROM approval_line WHERE approval_document_id = CAST(:documentId AS bigint)`,
        { documentId },
      );
      await db.execute(
        `DELETE FROM approval_document WHERE approval_document_id = CAST(:documentId AS bigint)`,
        { documentId },
      );
      await db.execute(
        `INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
         VALUES ('approval_document', CAST(:documentId AS bigint), '삭제', now(), CAST(:userId AS bigint), :beforeContent, NULL, now(), now())`,
        {
          documentId,
          userId: user.id,
          beforeContent: '문서번호=' + String(doc.documentNumber ?? '') + ', 제목=' + String(doc.title) + ', 상태=' + String(doc.approvalStatus),
        },
      );
      return {};
    });
  }

  @Post('/approval-documents/:approvalDocumentId/redraft')
  @HttpCode(200)
  async redraftApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const documentId = req.params['approvalDocumentId'];
    return transaction(async (db) => {
      // 가정: 조회 권한 = 기안자이거나 결재선에 포함된 결재자
      const rows = await db.query(
        `SELECT d.approval_form_id AS "approvalFormId",
                d.document_category_id AS "documentCategoryId",
                d.title AS "title",
                d.body AS "body",
                d.is_urgent AS "isUrgent",
                d.is_secret AS "isSecret",
                d.approval_status AS "approvalStatus"
           FROM approval_document d
          WHERE d.approval_document_id = CAST(:documentId AS bigint)
            AND (d.drafter_id = CAST(:userId AS bigint)
                 OR EXISTS (SELECT 1 FROM approval_line l
                             WHERE l.approval_document_id = d.approval_document_id
                               AND l.approver_id = CAST(:userId AS bigint)))`,
        { documentId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '원본 문서가 없거나 조회 권한이 없습니다.');
      }
      const src = rows[0];
      if (!REDRAFTABLE_STATUSES.includes(src.approvalStatus)) {
        throw new ApiError(409, 'APPROVAL_DOCUMENT_STATUS_MISMATCH', '재기안할 수 있는 상태의 문서가 아닙니다.');
      }
      let title = src.title;
      if (data.title !== undefined && data.title !== null) {
        if (typeof data.title !== 'string' || data.title.trim() === '' || data.title.length > 500) {
          throw new ApiError(400, 'VALIDATION_FAILED', '제목은 1~500자의 글자여야 합니다.');
        }
        title = data.title;
      }
      let body = src.body;
      if (data.body !== undefined && data.body !== null) {
        if (typeof data.body !== 'string') {
          throw new ApiError(400, 'VALIDATION_FAILED', '본문 형식이 올바르지 않습니다.');
        }
        body = data.body;
      }
      let isUrgent = src.isUrgent;
      if (data.isUrgent !== undefined && data.isUrgent !== null) {
        if (typeof data.isUrgent !== 'boolean') {
          throw new ApiError(400, 'VALIDATION_FAILED', '긴급결재 여부 형식이 올바르지 않습니다.');
        }
        isUrgent = data.isUrgent;
      }
      let isSecret = src.isSecret;
      if (data.isSecret !== undefined && data.isSecret !== null) {
        if (typeof data.isSecret !== 'boolean') {
          throw new ApiError(400, 'VALIDATION_FAILED', '보안문서 여부 형식이 올바르지 않습니다.');
        }
        isSecret = data.isSecret;
      }
      const emp = await db.query(
        `SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (emp.length === 0 || emp[0].departmentId === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '기안자의 소속 부서가 없어 재기안할 수 없습니다.');
      }
      const departmentId = emp[0].departmentId;
      // 채번: 기안자 부서 규칙 우선, 없으면 전사 공통 규칙
      const rules = await db.query(
        `SELECT numbering_rule_id AS "numberingRuleId"
           FROM numbering_rule
          WHERE target_type = 'DOCUMENT'
            AND (department_id = CAST(:departmentId AS bigint) OR department_id IS NULL)
          ORDER BY department_id NULLS LAST
          LIMIT 1
          FOR UPDATE`,
        { departmentId },
      );
      if (rules.length === 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서번호 채번 규칙이 없습니다.');
      }
      // 가정: 단위(일·월·연도)별 순번 초기화는 하지 않고 순번만 증가시킨다
      const numbered = await db.query(
        `UPDATE numbering_rule
            SET current_sequence = COALESCE(current_sequence, 0) + 1,
                updated_at = now()
          WHERE numbering_rule_id = CAST(:ruleId AS bigint)
          RETURNING COALESCE(prefix, '')
                    || CASE reset_unit WHEN 'DAY' THEN to_char(now(), 'YYYYMMDD') WHEN 'MONTH' THEN to_char(now(), 'YYYYMM') ELSE to_char(now(), 'YYYY') END
                    || lpad(current_sequence::text, digits, '0') AS "documentNumber"`,
        { ruleId: rules[0].numberingRuleId },
      );
      const created = await db.query(
        `INSERT INTO approval_document (approval_form_id, drafter_id, drafter_department_id, document_category_id, document_number, title, body, approval_status, is_urgent, is_secret, created_at, updated_at)
         VALUES (CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint), CAST(:categoryId AS bigint), :documentNumber, :title, :body, '기안', :isUrgent, :isSecret, now(), now())
         RETURNING approval_document_id AS "approvalDocumentId",
                   document_number AS "documentNumber",
                   approval_status AS "approvalStatus"`,
        {
          formId: src.approvalFormId,
          userId: user.id,
          departmentId,
          categoryId: src.documentCategoryId,
          documentNumber: numbered[0].documentNumber,
          title,
          body,
          isUrgent,
          isSecret,
        },
      );
      const result = created[0];
      // 결재선 복사 (처리 결과는 비운다)
      await db.execute(
        `INSERT INTO approval_line (approval_document_id, approver_id, line_group, sequence_no, created_at, updated_at)
         SELECT CAST(:newId AS bigint), approver_id, line_group, sequence_no, now(), now()
           FROM approval_line
          WHERE approval_document_id = CAST(:documentId AS bigint)`,
        { newId: result.approvalDocumentId, documentId },
      );
      await db.execute(
        `INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
         VALUES ('approval_document', CAST(:newId AS bigint), '등록', now(), CAST(:userId AS bigint), NULL, :afterContent, now(), now())`,
        {
          newId: result.approvalDocumentId,
          userId: user.id,
          afterContent: '재기안: 원본 문서 ID=' + String(documentId) + ', 새 문서번호=' + String(result.documentNumber),
        },
      );
      return result;
    });
  }
}

