import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr029107X9c9389Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 결과를 목록으로 보인다
  const [results, setResults] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'delete' | 'redraft'>('');
  const [documentId, setDocumentId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [isUrgent, setIsUrgent] = useState('');
  const [isSecret, setIsSecret] = useState('');

  const close = () => {
    setMode('');
    setDocumentId('');
    setTitle('');
    setBody('');
    setIsUrgent('');
    setIsSecret('');
  };

  const submitDelete = async () => {
    if (documentId === '') {
      throw new Error('삭제할 문서를 선택하세요.');
    }
    await call('DELETE', '/approval-documents/' + String(documentId), role);
    setResults([{ kind: '삭제', approvalDocumentId: documentId, at: new Date().toISOString() }, ...results]);
    notify('문서를 삭제했습니다.');
    close();
  };

  const submitRedraft = async () => {
    if (documentId === '') {
      throw new Error('재기안할 원본 문서를 선택하세요.');
    }
    const payload: Row = {};
    if (title.trim() !== '') payload.title = title;
    if (body.trim() !== '') payload.body = body;
    if (isUrgent !== '') payload.isUrgent = isUrgent === 'Y';
    if (isSecret !== '') payload.isSecret = isSecret === 'Y';
    const res = await call('POST', '/approval-documents/' + String(documentId) + '/redraft', role, payload);
    setResults([{ ...res, kind: '재기안', at: new Date().toISOString() }, ...results]);
    notify('재기안했습니다.');
    close();
  };

  const yesNo: [string, string][] = [
    ['Y', '예'],
    ['N', '아니오'],
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>재기안</h2>
        <Tiles items={[['처리 건수', results.filter((r) => r.kind === '재기안').length]]} />
      </section>
      <section className="box span-4">
        <h2>삭제</h2>
        <Tiles items={[['처리 건수', results.filter((r) => r.kind === '삭제').length]]} />
      </section>
      <section className="box span-4">
        <h2>문서 처리</h2>
        <Band>
          <button type="button" onClick={() => setMode('redraft')}>재기안</button>
          <button type="button" onClick={() => setMode('delete')}>삭제</button>
        </Band>
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length} />
        <DataTable
          rows={results}
          empty="처리한 문서가 없습니다."
          columns={[
            { key: 'kind', label: '구분' },
            {
              key: 'approvalDocumentId',
              label: '결재문서',
              render: (r) =>
                r.kind === '삭제' ? '삭제된 문서' : <RefName table="approval_document" role={role} value={r.approvalDocumentId} />,
            },
            { key: 'documentNumber', label: '문서번호' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => (r.approvalStatus ? <Badge value={r.approvalStatus} /> : '-') },
            { key: 'at', label: '처리 일시', render: (r) => <DateText value={r.at} time /> },
          ]}
        />
      </section>
      {mode === 'delete' && (
        <Drawer title="반려·회수 문서 삭제" onClose={close}>
          <Form onSubmit={submitDelete} submit="삭제" danger note="삭제한 문서는 복구할 수 없습니다. 반려 또는 회수 상태의 본인 문서만 삭제할 수 있습니다.">
            <Field label="결재문서" required wide>
              <LookupSelect table="approval_document" role={role} value={documentId} onChange={setDocumentId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'redraft' && (
        <Drawer title="재기안" onClose={close}>
          <Form onSubmit={submitRedraft} submit="재기안" note="비워 둔 항목은 원본 문서의 값을 그대로 사용하며, 새 문서번호가 부여됩니다.">
            <Field label="원본 결재문서" required wide>
              <LookupSelect table="approval_document" role={role} value={documentId} onChange={setDocumentId} />
            </Field>
            <Field label="문서 제목" wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={isUrgent} onChange={setIsUrgent} options={yesNo} placeholder="원본과 같게" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={isSecret} onChange={setIsSecret} options={yesNo} placeholder="원본과 같게" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
